interface Entity {
  readonly id: string;
}

interface HiddenBase {
  readonly inherited: string;
  mutableInherited: number;
}

export type UserId = string & { readonly __brand: "UserId" };
export type Mode = "fast" | "careful";
export type ClosedFlags = { readonly [K in Mode]: boolean };
export type OpenConditional<T> = T extends string ? { text: T } : { value: T };
export type OpenIndexed<T> = T[keyof T];
export type TemplateText = `item-${string}`;
export type UpperText = Uppercase<string>;
export type Pair = [string, number];
export type LabeledPair = [left: string, right: number];
export type TruthTuple = [true, false];

export enum Direction {
  Up,
  Down,
}

export declare const uniqueToken: unique symbol;

export interface User extends Entity {
  name: string;
  nickname?: string | null;
  readonly flags: ClosedFlags;
  [rank: number]: string;
}

export interface InheritedSurface extends HiddenBase {
  own: boolean;
}

export interface ReadonlyDictionary {
  readonly [key: string]: number;
}

export interface Page<T> {
  items: T[];
}

export declare function parse(value: string): UserId;
export declare function parse(value: number): User;
export declare function select<T extends Entity = User>(value: T, mode?: Mode): T;
export declare const deferred: OpenConditional<unknown>;
export declare const users: Page<User>;
